"""Read-only inspection of the exact marked synthetic full-host database."""
import datetime,json,sqlite3
from pathlib import Path
repo=Path(__file__).resolve().parents[2];root=repo/'.lucille-qa-runtime/lucille-synthetic-full22';reports=repo/'.lucille-qa-runtime/lucille-synthetic-real22/reports'
assert (root/'.lucille-isolated').read_bytes()==b'synthetic-data-only\n';db=root/'lucille-phase1.sqlite3';assert db.resolve().parent==root.resolve()
c=sqlite3.connect(db.resolve().as_uri()+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
def rows(sql,args=()):return [dict(x) for x in c.execute(sql,args)]
scope='phase22-long-heldout-v3'
result={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'database':'isolated lucille-synthetic-full22/lucille-phase1.sqlite3','access':'SQLite URI mode=ro; no external writes','integrity':rows('PRAGMA integrity_check'),'foreign_key_violations':rows('PRAGMA foreign_key_check'),'stale_current_vectors':rows("SELECT count(*) AS count FROM memory_vectors v JOIN memories m ON m.id=v.memory_id JOIN embedding_spaces e ON e.id=v.space_id WHERE e.active=1 AND (m.state!='active' OR m.version!=v.memory_version)"),'orphan_vectors':rows('SELECT count(*) AS count FROM memory_vectors v LEFT JOIN memories m ON m.id=v.memory_id WHERE m.id IS NULL'),'duplicate_active_fingerprints':rows("SELECT m.scope,m.project,q.subject,q.property,q.value,count(*) AS count FROM memories m JOIN memory_quality q ON q.memory_id=m.id WHERE m.state='active' GROUP BY m.scope,m.project,q.subject,q.property,q.value HAVING count(*)>1"),'scope_snapshots':{}}
for project in ['candeia','candeia2']:
 result['scope_snapshots'][project]={'memories':rows('SELECT m.id,m.state,m.version,m.kind,q.subject,q.property,q.value,q.temporal,q.facets_json,q.replaces_id,q.replaces_version,(SELECT count(*) FROM memory_provenance p WHERE p.memory_id=m.id) AS provenance_count,(SELECT count(*) FROM memory_revisions r WHERE r.memory_id=m.id) AS revision_count FROM memories m JOIN memory_quality q ON q.memory_id=m.id WHERE m.scope=? AND m.project=? ORDER BY q.subject,q.property,m.state',(scope,project)),'tombstones':rows('SELECT id,kind,claim_digest,deleted_at FROM memory_tombstones WHERE scope=? AND project=?',(scope,project)),'queue':rows('SELECT state,count(*) AS count FROM extraction_jobs WHERE scope=? AND project=? GROUP BY state',(scope,project))}
result['fault_jobs']=rows("SELECT j.scope,j.id,j.state,j.attempts,j.lease_token IS NULL AS lease_revoked,j.lease_until IS NULL AS lease_expiry_cleared,(SELECT count(*) FROM learning_inputs i WHERE i.job_id=j.id) AS remaining_input_rows FROM extraction_jobs j WHERE j.scope LIKE 'phase22-v3-%heldout-%' ORDER BY j.scope")
result['file_sizes']={p.name:p.stat().st_size for p in root.glob('lucille-phase1.sqlite3*') if p.is_file()};c.close()
out=reports/'v3-canonical-final-review.json';assert not out.exists();out.write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({k:result[k] for k in ['integrity','foreign_key_violations','stale_current_vectors','orphan_vectors','duplicate_active_fingerprints','fault_jobs']}))
